#!/usr/bin/env bash
# ov-no-auto-capture spike, generated by build.sh from wrapper_init.py: wrapper, plugin.yaml, stub, render and driver are inlined.
set -u
W=$(mktemp -d); mkdir -p $W/spike
cat > $W/wrapper_init.py <<'SPIKEEOF'
"""OpenViking in tools-only mode: the upstream provider with recall and capture off.

Hermes loads this bundled dir as plugins.memory.openviking_tools. The six
viking_* tools and their handlers stay upstream's; prefetch, sync, session
commits and memory mirroring do nothing.
"""

from plugins.memory.openviking import OpenVikingMemoryProvider

_PROMPT = (
    "# OpenViking Knowledge Base\n"
    "Tools: viking_search, viking_read, viking_browse, viking_remember, "
    "viking_forget, viking_add_resource. Use them only when the user or a "
    "skill asks for OpenViking."
)


class OpenVikingToolsProvider(OpenVikingMemoryProvider):
    def initialize(self, session_id: str, **kwargs) -> None:
        # A non-primary context clears _writes_enabled, the upstream gate on
        # sync_turn, on_session_end, the commit in on_session_switch and
        # on_memory_write.
        super().initialize(session_id, **{**kwargs, "agent_context": "flush"})

    def prefetch(self, query: str, *, session_id: str = "") -> str:
        return ""

    def system_prompt_block(self) -> str:
        return _PROMPT


def register(ctx) -> None:
    ctx.register_memory_provider(OpenVikingToolsProvider())
SPIKEEOF
cat > $W/plugin.yaml <<'SPIKEEOF'
name: openviking_tools
version: 0.1.0
description: "OpenViking tools only: no automatic recall or capture."
pip_dependencies:
  - httpx
requires_env: []
hooks: []
SPIKEEOF
cat > $W/render.py <<'SPIKEEOF'
"""Render the hermes data dir the `config` prestart task writes, from hermes.hcl.

usage: render.py HERMES_HCL OUT_DIR
Takes config.yaml and the bifrost model-provider files verbatim from the
jobspec's template heredocs, filling the few Terraform variables they use.
"""

import re
import sys
from pathlib import Path

hcl = Path(sys.argv[1]).read_text()
out = Path(sys.argv[2])

templates = dict(
    (dest, data)
    for data, dest in re.findall(
        r'data = <<EOF\n(.*?)\nEOF\n\s*\n\s*destination = "([^"]+)"', hcl, re.S
    )
)
need = [
    "local/config.yaml",
    "local/model-providers/bifrost/__init__.py",
    "local/model-providers/bifrost/plugin.yaml",
]
missing = [n for n in need if n not in templates]
if missing:
    sys.exit(f"render: templates not found in jobspec: {missing}")

def fill(text: str) -> str:
    text = text.replace("${hermes_dashboard_public_url}", "http://127.0.0.1:9119")
    return text.replace("$${", "${")

files = {
    "config.yaml": fill(templates["local/config.yaml"]),
    "plugins/model-providers/bifrost/__init__.py": fill(templates[need[1]]),
    "plugins/model-providers/bifrost/plugin.yaml": fill(templates[need[2]]),
    # The OPENVIKING_* lines setup.sh writes to /opt/data/.env, with the
    # values services.tf passes (openviking_proxy_placeholder, _account, _user).
    ".env": "\n".join([
        "OPENVIKING_API_KEY=unused-the-sidecar-supplies-the-token",
        "OPENVIKING_ACCOUNT=lab",
        "OPENVIKING_USER=jasper",
        "OPENVIKING_ENDPOINT=http://127.0.0.1:1934",
        "HERMES_YOLO_MODE=true",
        "HERMES_HOME=/opt/data",
        "BIFROST_API_KEY=spike-bifrost-key",
    ]) + "\n",
}
for rel, body in files.items():
    p = out / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(body)
for d in ["sessions", "memories", "cron", "hooks", "logs", "skills"]:
    (out / d).mkdir(exist_ok=True)
print("render: wrote", ", ".join(sorted(files)))
SPIKEEOF
cat > $W/spike/stub.py <<'SPIKEEOF'
"""Two loopback stubs for the hermes spike, logging every request as JSON lines.

127.0.0.1:1934 stands in for ov_auth_proxy (OpenViking API).
127.0.0.1:8080 stands in for Bifrost (OpenAI chat completions): it answers the
first turn with a viking_search tool call and the next with SPIKE-DONE.
"""

import json
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

LOG = sys.argv[1] if len(sys.argv) > 1 else "/tmp/requests.jsonl"
lock = threading.Lock()

MEMORY = {
    "uri": "viking://user/jasper/memories/spike-probe.md",
    "abstract": "SPIKE-MEMORY: the lab account remembers the spike probe.",
    "score": 0.93,
    "context_type": "memory",
}


def log(port, handler, body):
    entry = {
        "port": port,
        "method": handler.command,
        "path": handler.path,
        "headers": {k.lower(): v for k, v in handler.headers.items()},
        "body": body[:2000].decode("utf-8", "replace"),
    }
    with lock, open(LOG, "a") as f:
        f.write(json.dumps(entry) + "\n")


class Base(BaseHTTPRequestHandler):
    port = 0

    def log_message(self, *args):
        pass

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n else b""

    def _json(self, obj, status=200):
        data = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def handle_any(self):
        body = self._body()
        log(self.port, self, body)
        self.respond(body)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = handle_any


class Viking(Base):
    port = 1934

    def respond(self, body):
        p = self.path.split("?")[0]
        if p == "/health":
            return self._json({"status": "ok", "healthy": True, "version": "0.4.17"})
        if p.startswith("/api/v1/search/"):
            return self._json({"status": "ok", "result": {
                "memories": [MEMORY], "resources": [], "skills": [], "total": 1}})
        if p == "/api/v1/fs/ls":
            return self._json({"status": "ok", "result": []})
        if p.startswith("/api/v1/sessions"):
            return self._json({"status": "ok", "result": {"session_id": "spike", "messages": []}})
        if p == "/api/v1/system/status":
            return self._json({"status": "ok", "result": {"initialized": True, "user": "jasper"}})
        return self._json({"status": "ok", "result": {}})


def completion(content=None, tool_call=None):
    msg = {"role": "assistant", "content": content}
    if tool_call:
        msg["tool_calls"] = [tool_call]
    return {
        "id": "chatcmpl-spike", "object": "chat.completion", "created": 0,
        "model": "ollama/deepseek-v4.1-flash",
        "choices": [{"index": 0, "message": msg,
                     "finish_reason": "tool_calls" if tool_call else "stop"}],
        "usage": {"prompt_tokens": 10, "completion_tokens": 5, "total_tokens": 15},
    }


class Bifrost(Base):
    port = 8080

    def respond(self, body):
        p = self.path.split("?")[0]
        if p.endswith("/models"):
            return self._json({"object": "list", "data": [
                {"id": "ollama/deepseek-v4.1-flash", "object": "model", "context_length": 128000}]})
        if not p.endswith("/chat/completions"):
            return self._json({"error": {"message": "stub: unsupported " + p}}, 404)
        req = json.loads(body or b"{}")
        msgs = req.get("messages", [])
        tools = [t.get("function", {}).get("name") for t in req.get("tools") or []]
        saw_tool = any(m.get("role") == "tool" for m in msgs)
        users = [m for m in msgs if m.get("role") == "user"]
        last_user = str(users[-1].get("content") if users else "")
        if not saw_tool and "SEARCH-OV" in last_user and "viking_search" in tools:
            resp = completion(tool_call={"id": "call_spike", "type": "function", "function": {
                "name": "viking_search", "arguments": json.dumps({"query": "spike probe"})}})
        elif saw_tool and "SEARCH-OV" in last_user:
            resp = completion(content="SPIKE-DONE")
        else:
            resp = completion(content="PLAIN-REPLY tools=" + ",".join(t or "" for t in tools))
        if req.get("stream"):
            return self._stream(resp)
        return self._json(resp)

    def _stream(self, resp):
        msg = resp["choices"][0]["message"]
        delta = {"role": "assistant"}
        if msg.get("content"):
            delta["content"] = msg["content"]
        if msg.get("tool_calls"):
            delta["tool_calls"] = [dict(tc, index=0) for tc in msg["tool_calls"]]
        chunks = [
            {"id": resp["id"], "object": "chat.completion.chunk", "created": 0, "model": resp["model"],
             "choices": [{"index": 0, "delta": delta, "finish_reason": None}]},
            {"id": resp["id"], "object": "chat.completion.chunk", "created": 0, "model": resp["model"],
             "choices": [{"index": 0, "delta": {}, "finish_reason": resp["choices"][0]["finish_reason"]}],
             "usage": resp["usage"]},
        ]
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.end_headers()
        for c in chunks:
            self.wfile.write(b"data: " + json.dumps(c).encode() + b"\n\n")
        self.wfile.write(b"data: [DONE]\n\n")
        self.wfile.flush()


if __name__ == "__main__":
    servers = [ThreadingHTTPServer(("127.0.0.1", 1934), Viking),
               ThreadingHTTPServer(("127.0.0.1", 8080), Bifrost)]
    for s in servers[1:]:
        threading.Thread(target=s.serve_forever, daemon=True).start()
    servers[0].serve_forever()
SPIKEEOF
cat > $W/spike/driver.py <<'SPIKEEOF'
"""Drive Hermes's real agent path (agent_init -> load_memory_provider ->
MemoryManager) with the openviking_tools provider, against loopback stubs.

Phases: init (with a stale pending-session marker seeded), a plain turn,
/new (the CLI's commit_session_boundary_async), a built-in memory write,
an explicit viking_search turn, then shutdown. Exits 0 only when every check passes.
"""

import json
import logging
import sys
import time

sys.path.insert(0, "/opt/hermes")
logging.basicConfig(level=logging.INFO, stream=sys.stderr,
                    format="%(name)s %(levelname)s %(message)s")

LOG = "/tmp/requests.jsonl"
VIKING_TOOLS = {"viking_search", "viking_read", "viking_browse",
                "viking_remember", "viking_forget", "viking_add_resource"}
FAIL = 0


def ov_requests():
    try:
        with open(LOG) as f:
            return [e for e in map(json.loads, f) if e["port"] == 1934]
    except FileNotFoundError:
        return []


def check(name, ok, detail=""):
    global FAIL
    print(("PASS: " if ok else "FAIL: ") + name + (f" ({detail})" if detail else ""))
    if not ok:
        FAIL = 1


def show(label, reqs):
    print(f"-- 1934 requests during {label}: {len(reqs)}")
    for e in reqs:
        print("  ", e["method"], e["path"][:100])


def memory_traffic(reqs):
    """Recall, profile reads, session uploads and commits: anything but health/identity."""
    bad = ("/api/v1/search", "/api/v1/sessions", "/api/v1/content", "/api/v1/fs")
    return [e for e in reqs if e["path"].split("?")[0].startswith(bad)]


from hermes_cli.config import load_config  # noqa: E402
from run_agent import AIAgent  # noqa: E402

cfg = load_config()
print("memory.provider in config:", cfg["memory"]["provider"])
toolsets = cfg["platform_toolsets"]["telegram"]

seen = 0
agent = AIAgent(base_url="http://127.0.0.1:8080/v1", api_key="spike", provider="custom",
                model="ollama/deepseek-v4.1-flash", quiet_mode=True, platform="telegram",
                user_id="4242", enabled_toolsets=toolsets, session_id="spike-s1",
                skip_context_files=True)
mm = agent._memory_manager
providers = [p for p in (mm.providers if mm else []) if p.name != "builtin"]
prov = providers[0] if providers else None
check("provider loaded and activated", prov is not None,
      f"{type(prov).__module__}.{type(prov).__name__}, name={getattr(prov, 'name', None)!r}" if prov else "none")
if prov is None:
    sys.exit(1)
check("provider is the wrapper module", type(prov).__module__ == "plugins.memory.openviking_tools")
check("writes are off after initialize", prov._writes_enabled is False)
tool_names = {t.get("function", {}).get("name") for t in agent.tools or []}
check("all six viking_* tools on the agent's tool surface", VIKING_TOOLS <= tool_names,
      ",".join(sorted(n for n in tool_names if n and n.startswith("viking_"))))
block = mm.build_system_prompt()
check("system prompt carries the static block", "skill asks for OpenViking" in block)
time.sleep(3)  # give any startup recovery thread time to post
reqs = ov_requests(); show("init", reqs[seen:])
check("no commit of the seeded stale session at init",
      not [e for e in reqs[seen:] if "stale-spike" in e["path"]])
check("no memory traffic at init", not memory_traffic(reqs[seen:]))
seen = len(reqs)

r1 = agent.run_conversation("Hello there, what is the weather like on Mars today?")
print("plain turn reply:", str(r1.get("final_response"))[:120])
check("plain turn got a reply without a tool call", str(r1.get("final_response", "")).startswith("PLAIN-REPLY"))
mm.flush_pending(timeout=15)
time.sleep(1)
reqs = ov_requests(); show("plain turn", reqs[seen:])
check("no search/session/commit during the plain turn", not memory_traffic(reqs[seen:]))
seen = len(reqs)

old_sid = agent.session_id
agent.session_id = "spike-s2"
mm.commit_session_boundary_async(list(r1["messages"]), new_session_id="spike-s2",
                                 parent_session_id=old_sid, reason="new_session")
mm.flush_pending(timeout=15)
mm.on_memory_write("add", "memory", "The spike prefers tea.")
time.sleep(3)
reqs = ov_requests(); show("/new and memory write", reqs[seen:])
check("no search/session/commit at /new or on a built-in memory write", not memory_traffic(reqs[seen:]))
check("provider rotated to the new session id", prov._session_id == "spike-s2", prov._session_id)
seen = len(reqs)

r2 = agent.run_conversation("Please SEARCH-OV for the spike probe.")
print("search turn reply:", str(r2.get("final_response"))[:120])
mm.flush_pending(timeout=15)
time.sleep(1)
reqs = ov_requests(); show("explicit search turn", reqs[seen:])
searches = [e for e in reqs[seen:] if e["path"].startswith("/api/v1/search/")]
check("explicit viking_search reached the stub", len(searches) >= 1, f"{len(searches)} search request(s)")
check("model got the tool result back", str(r2.get("final_response", "")) == "SPIKE-DONE")
check("no session upload or commit during the search turn",
      not [e for e in reqs[seen:] if e["path"].startswith("/api/v1/sessions")])
seen = len(reqs)

agent.shutdown_memory_provider(list(r2["messages"]))
time.sleep(2)
reqs = ov_requests(); show("shutdown", reqs[seen:])
check("no search/session/commit at shutdown", not memory_traffic(reqs[seen:]))

print("== driver result: FAIL=%d" % FAIL)
sys.exit(FAIL)
SPIKEEOF
ID=ovtools$$
BASE=ghcr.io/jasperhg90/hermes:0.22.2-1
IMG=$ID-img
cleanup() { docker rm -f $ID-c >/dev/null 2>&1; docker rmi -f $IMG >/dev/null 2>&1; }
trap cleanup EXIT

echo "== build: the 0.22.2-1 image plus openviking_tools in the bundled memory dir"
mkdir -p $W/ctx/openviking_tools
cp $W/wrapper_init.py $W/ctx/openviking_tools/__init__.py
cp $W/plugin.yaml $W/ctx/openviking_tools/plugin.yaml
printf '%s\n' "FROM $BASE" "COPY openviking_tools /opt/hermes/plugins/memory/openviking_tools" > $W/ctx/Dockerfile
docker build -q -t $IMG $W/ctx || exit 2

echo "== render /opt/data from hermes.hcl, provider switched to openviking_tools"
python3 -I $W/render.py deployments/applications/services/hermes.hcl $W/data || exit 2
sed -i 's/^  provider: "openviking"$/  provider: "openviking_tools"/' $W/data/config.yaml
grep -n 'provider: "openviking_tools"' $W/data/config.yaml || { echo "provider line not switched"; exit 2; }
# A pending-session marker left by a dead run, as a crash mid-session leaves it.
mkdir -p $W/data/openviking/pending_sessions
echo '{"session_id": "stale-spike", "owner_run_id": "deadrun", "connection_key": ""}' \
  > $W/data/openviking/pending_sessions/stale-spike.json

# --network none: loopback only, so nothing leaves the container.
docker create --name $ID-c --network none --entrypoint sh \
  -e HERMES_HOME=/opt/data -e HERMES_YOLO_MODE=true \
  -e OPENVIKING_ENDPOINT=http://127.0.0.1:1934 -e OPENVIKING_API_KEY=unused-the-sidecar-supplies-the-token \
  -e OPENVIKING_ACCOUNT=lab -e OPENVIKING_USER=jasper -e BIFROST_API_KEY=spike-bifrost-key \
  $IMG -c 'chown -R hermes:hermes /opt/data && cd /opt/hermes && (python3 -u /spike/stub.py /tmp/requests.jsonl &) && sleep 2 \
    && echo "== hermes memory status" && hermes memory status 2>&1 | head -20 \
    && echo "== driver" && python3 -u /spike/driver.py' >/dev/null
docker cp $W/data/. $ID-c:/opt/data/
docker cp $W/spike $ID-c:/spike
docker start -a $ID-c
RC=$?
echo "== result: driver exit $RC"
exit $RC
